CREATE TABLE accounts.trade_accounts (
  org_id uuid PRIMARY KEY REFERENCES identity.orgs(id), tier credit_tier NOT NULL DEFAULT 'new', terms_days smallint NOT NULL DEFAULT 0, limit_cents bigint NOT NULL DEFAULT 0,
  status text NOT NULL DEFAULT 'pending' CHECK (status IN ('pending','active','on_hold','closed')), nca_review boolean NOT NULL DEFAULT true, price_list_id uuid REFERENCES catalog.price_lists(id), updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE accounts.credit_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES identity.orgs(id), requested_limit_cents bigint, requested_terms_days smallint, est_weekly_spend_cents bigint, business_type text, submitted_at timestamptz NOT NULL DEFAULT now(), decision text, decided_by uuid, second_approver uuid, decided_at timestamptz);
CREATE TABLE accounts.documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES identity.orgs(id), kind text NOT NULL, storage_url text NOT NULL, verified boolean NOT NULL DEFAULT false, expires_on date);
CREATE TABLE accounts.bureau_reports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES identity.orgs(id), provider text NOT NULL, risk text, payload jsonb, consent_ref text NOT NULL, pulled_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts.credit_limits (id bigserial PRIMARY KEY, org_id uuid REFERENCES identity.orgs(id), tier credit_tier NOT NULL, limit_cents bigint NOT NULL, terms_days smallint NOT NULL, reasons text[], proposed_by text NOT NULL DEFAULT 'system', approved_by uuid, effective_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts.credit_events (id bigserial PRIMARY KEY, org_id uuid, kind text NOT NULL, data jsonb, at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts.sureties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid REFERENCES identity.orgs(id), surety_name text NOT NULL, id_ref text, amount_cents bigint, signed_at timestamptz);
CREATE TABLE accounts.invoices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number text UNIQUE NOT NULL, org_id uuid REFERENCES identity.orgs(id), order_id uuid REFERENCES sales.orders(id), issued_on date NOT NULL, due_on date NOT NULL, subtotal_ex_vat_cents bigint NOT NULL, vat_cents bigint NOT NULL, total_inc_vat_cents bigint NOT NULL, status text NOT NULL DEFAULT 'open', financed_by text);
CREATE TABLE accounts.invoice_lines (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid REFERENCES accounts.invoices(id), description text NOT NULL, qty numeric(12,3), unit_ex_vat_cents bigint, total_ex_vat_cents bigint);
CREATE TABLE accounts.allocations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid REFERENCES accounts.invoices(id), payment_id uuid, amount_cents bigint NOT NULL, allocated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE accounts.collection_actions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid REFERENCES accounts.invoices(id), step text NOT NULL CHECK (step IN ('reminder_pre','due_notice','reminder_1','call_7','hold_14','demand_30')), scheduled_at timestamptz NOT NULL, done_at timestamptz, by_user uuid);
CREATE TABLE accounts.disputes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), invoice_id uuid REFERENCES accounts.invoices(id), opened_at timestamptz NOT NULL DEFAULT now(), reason text, photo_urls text[], temperature_evidence jsonb, outcome text);
